import React, { useState } from 'react';
import { Card, CardContent, Typography, Box, Divider, Button, TextField, CircularProgress, Snackbar, Alert, Dialog, DialogTitle, DialogContent, DialogActions } from '@mui/material';

const FrameDetailsPage = ({ frames, onBack }) => {
    const API_BASE = 'http://localhost:8000';
    const [blurStrengths, setBlurStrengths] = useState({});
    const [processing, setProcessing] = useState({});
    const [previewUrls, setPreviewUrls] = useState({});
    const [toast, setToast] = useState({ open: false, severity: 'success', message: '' });
    const [selectedPolicy, setSelectedPolicy] = useState(null);
    // Show ALL frames, not just non-compliant ones
    if (!frames || frames.length === 0) return <Typography>No frames found.</Typography>;
    const handleBack = () => {
        if (onBack) {
            onBack();
        }
    };
    return (
        <Box sx={{ p: 4 }}>
            <Button variant="outlined" color="primary" sx={{ mb: 2 }} onClick={handleBack}>
                ← Back
            </Button>
            <Typography variant="h4" color="primary" sx={{ mb: 3, fontWeight: 'bold' }}>
                Detailed Frame Report
            </Typography>
            {frames.map((frame, idx) => (
                <Card key={idx} sx={{ mb: 2, boxShadow: 2 }}>
                    <CardContent>
                        <Typography variant="h6" sx={{ fontWeight: 'bold' }}>Frame {frame.frame_index !== undefined ? frame.frame_index + 1 : idx + 1}</Typography>
                        <Typography variant="body2">Timestamp: <b>{frame.timestamp !== undefined ? frame.timestamp : 'N/A'}</b></Typography>
                        {frame.preview_path && <img src={frame.preview_path} alt={`Frame ${idx + 1}`} style={{ maxWidth: 320, borderRadius: 8, marginBottom: 8 }} />}
                        <Divider sx={{ my: 1 }} />
                        <Typography variant="body2">Category: <b>{frame.visual_analysis?.category || frame.category || 'N/A'}</b></Typography>
                        <Typography variant="body2">Confidence: <b>{frame.visual_analysis?.confidence !== undefined ? frame.visual_analysis.confidence : frame.confidence || 'N/A'}</b></Typography>
                        <Typography variant="body2">Violation Detected: <b>{frame.visual_analysis?.violation_detected !== undefined ? (frame.visual_analysis.violation_detected ? 'Yes' : 'No') : (frame.combined_violation ? 'Yes' : 'No')}</b></Typography>
                        <Divider sx={{ my: 1 }} />
                        {frame.blip_description?.description && frame.blip_description.description.trim() !== '' && (
                            <Typography variant="body2">BLIP Description: <b>{frame.blip_description.description}</b></Typography>
                        )}
                        {(!frame.blip_description?.description || frame.blip_description.description.trim() === '') && (
                            <Typography variant="body2">BLIP Description: <b>N/A</b></Typography>
                        )}
                        {frame.ocr_text?.text && frame.ocr_text.text.trim() !== '' && (
                            <Typography variant="body2">OCR Text: <b>{frame.ocr_text.text}</b></Typography>
                        )}
                        {(!frame.ocr_text?.text || frame.ocr_text.text.trim() === '') && (
                            <Typography variant="body2">OCR Text: <b>N/A</b></Typography>
                        )}
                        {frame.ocr_text?.extracted_items && frame.ocr_text.extracted_items.length > 0 && (
                            <Typography variant="body2">OCR Items: <b>{frame.ocr_text.extracted_items.map((item, i) => item.text).join(', ')}</b></Typography>
                        )}
                        {/* DB evidence bullets */}
                        {frame.retrieved_policies && frame.retrieved_policies.length > 0 && (
                            <Box component="ul" sx={{ pl: 2, mt: 1 }}>
                                {frame.retrieved_policies.map((p, i) => (
                                    <Box component="li" key={i} sx={{ cursor: 'pointer', mb: 0.8 }} onClick={() => setSelectedPolicy(p)}>
                                        <Typography variant="body2"><strong>{p.policy_info?.category || p.category || 'policy'}</strong> — {p.policy_info?.title || p.policy_info?.description || p.description || 'No description'}</Typography>
                                        <Typography variant="caption" color="text.secondary">Source: {p.policy_info?.source || p.source || 'unknown'} | sim: {p.similarity ? Number(p.similarity).toFixed(3) : 'N/A'}</Typography>
                                    </Box>
                                ))}
                            </Box>
                        )}
                        {/* Policy, Examples, Action Required from RAG if available */}
                        {frame.policy && frame.policy.description && (
                            <Typography variant="body2">Policy: <b>{frame.policy.description}</b></Typography>
                        )}
                        {frame.examples && frame.examples.length > 0 && (
                            <Typography variant="body2">Examples: <b>{frame.examples.join(', ')}</b></Typography>
                        )}
                        {frame.action_required && (
                            <Typography variant="body2">Action Required: <b>{frame.action_required}</b></Typography>
                        )}
                        <Divider sx={{ my: 1 }} />
                        <Typography variant="body2">Preview Path: <b>{frame.preview_path || 'N/A'}</b></Typography>
                        <Typography variant="body2">Frame Index: <b>{frame.frame_index !== undefined ? frame.frame_index : idx}</b></Typography>
                        {/* Clear policy/action bullets */}
                        {frame.policy && (
                            <Box sx={{ mt: 1 }}>
                                <Typography variant="subtitle2">Policy summary</Typography>
                                <Box component="ul" sx={{ pl: 2, mt: 0.5 }}>
                                    <li><Typography variant="body2">{frame.policy.description || frame.policy.summary || 'No policy text available'}</Typography></li>
                                    {frame.policy.action_required && <li><Typography variant="body2"><strong>Action required:</strong> {frame.policy.action_required}</Typography></li>}
                                    {frame.policy.severity && <li><Typography variant="body2"><strong>Severity:</strong> {frame.policy.severity}</Typography></li>}
                                </Box>
                            </Box>
                        )}
                        {/* Blur controls and preview */}
                        <Box sx={{ mt: 1, display: 'flex', gap: 1, alignItems: 'center' }}>
                            <TextField size="small" label="Blur px" type="number" value={blurStrengths[idx] ?? 10} onChange={(e) => setBlurStrengths(s => ({ ...s, [idx]: Number(e.target.value) }))} sx={{ width: 120 }} />
                            {processing[idx] ? (
                                <CircularProgress size={20} />
                            ) : (
                                <Button size="small" variant="contained" onClick={async () => {
                                    const strength = Number(blurStrengths[idx] ?? 10) || 10;
                                    setProcessing(p => ({ ...p, [idx]: true }));
                                    try {
                                        // Try to use video id if present on frame
                                        const vid = frame.video_id || frame.videoId || frame.video || null;
                                            // const payload = {
                                            //     type: 'frame_fix',
                                            //     frame: frame.frame_index !== undefined ? frame.frame_index : frame.frame,
                                            //     timestamp: frame.timestamp || null,
                                            //     action: 'blur',
                                            //     options: { strength },
                                            //     source_path: frame.source_path || frame.preview_path || null
                                            // };
                                            // let resp = null;
                                        let effectiveVid = vid;
                                        // If no video id, first save a minimal report to obtain one
                                        if (!effectiveVid) {
                                            try {
                                                const savePayload = {
                                                    filename: frame.video_title || frame.filename || `frame_preview_${idx}`,
                                                    video_title: frame.video_title || frame.filename || `frame_preview_${idx}`,
                                                    frame_preview: {
                                                        frame_index: frame.frame_index,
                                                        timestamp: frame.timestamp,
                                                        preview_path: frame.preview_path || null,
                                                        category: frame.visual_analysis?.category || frame.category || null
                                                    }
                                                };
                                                const saveResp = await fetch(`${API_BASE}/api/videos/save-or-id`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(savePayload) });
                                                if (saveResp.ok) {
                                                    const sdata = await saveResp.json().catch(() => null);
                                                    if (sdata && sdata.video_id) {
                                                        effectiveVid = sdata.video_id;
                                                    }
                                                }
                                            } catch (e) {
                                                // ignore save failure and proceed to attempt apply (it will fail if backend requires id)
                                                // eslint-disable-next-line no-console
                                                console.warn('save-or-id failed', e);
                                            }
                                        }

                                        // Prefer the single-frame synchronous blur endpoint to get immediate proof
                                        if (effectiveVid) {
                                            try {
                                                const blurPayload = {
                                                    preview_path: frame.preview_path || frame.source_path || null,
                                                    options: { strength }
                                                };
                                                const blurResp = await fetch(`${API_BASE}/api/videos/${effectiveVid}/apply-frame-blur`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(blurPayload) });
                                                if (!blurResp.ok) {
                                                    const txt = await blurResp.text().catch(() => '');
                                                    // eslint-disable-next-line no-alert
                                                    alert('Blur failed: ' + (txt || blurResp.statusText || blurResp.status));
                                                } else {
                                                    const bdata = await blurResp.json().catch(() => null);
                                                    if (bdata && bdata.result_path) {
                                                        setPreviewUrls(p => ({ ...p, [idx]: bdata.result_path }));
                                                        setToast({ open: true, severity: 'success', message: 'Frame blurred — preview ready' });
                                                    } else {
                                                        setToast({ open: true, severity: 'warning', message: 'Blur completed but no preview returned' });
                                                    }
                                                }
                                            } catch (e) {
                                                // eslint-disable-next-line no-console
                                                console.error('Frame blur request failed', e);
                                                setToast({ open: true, severity: 'error', message: 'Frame blur request failed' });
                                            }
                                        } else {
                                            // No video id available; inform user to save or use the main apply flow
                                            setToast({ open: true, severity: 'error', message: 'No video id available — save the report first' });
                                        }
                                    } catch (err) {
                                        // eslint-disable-next-line no-console
                                        console.error('Apply blur failed', err);
                                        // eslint-disable-next-line no-alert
                                        alert('Apply blur failed: ' + (err.message || err));
                                    }
                                    setProcessing(p => ({ ...p, [idx]: false }));
                                }}>Apply Blur & Preview</Button>
                            )}
                        </Box>
                        {previewUrls[idx] && (
                            <Box sx={{ mt: 1 }}>
                                <Typography variant="body2">Preview:</Typography>
                                {/\.(jpe?g|png|webp|gif)$/i.test(previewUrls[idx]) ? (
                                    <img src={previewUrls[idx]} alt={`Preview ${idx}`} style={{ maxWidth: 480, borderRadius: 8, marginTop: 8 }} />
                                ) : (
                                    <video src={previewUrls[idx]} controls style={{ maxWidth: 480, borderRadius: 8, marginTop: 8 }} />
                                )}
                            </Box>
                        )}
                        <Snackbar open={toast.open} autoHideDuration={4000} onClose={() => setToast(t => ({ ...t, open: false }))}>
                            <Alert onClose={() => setToast(t => ({ ...t, open: false }))} severity={toast.severity} sx={{ width: '100%' }}>
                                {toast.message}
                            </Alert>
                        </Snackbar>
                        <Dialog open={Boolean(selectedPolicy)} onClose={() => setSelectedPolicy(null)} maxWidth="sm" fullWidth>
                            <DialogTitle>{selectedPolicy?.policy_info?.title || selectedPolicy?.policy_info?.category || 'Policy detail'}</DialogTitle>
                            <DialogContent dividers>
                                <Typography variant="subtitle2" sx={{ mb: 1 }}>{selectedPolicy?.policy_info?.category || selectedPolicy?.category}</Typography>
                                <Typography variant="body2" sx={{ whiteSpace: 'pre-wrap' }}>{selectedPolicy?.policy_info?.description || selectedPolicy?.description || 'No description available.'}</Typography>
                                {selectedPolicy?.policy_info?.source && <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>Source: {selectedPolicy.policy_info.source}</Typography>}
                            </DialogContent>
                            <DialogActions>
                                <Button onClick={() => setSelectedPolicy(null)}>Close</Button>
                            </DialogActions>
                        </Dialog>
                        {/* Add more fields as needed for full model analysis */}
                    </CardContent>
                </Card>
            ))}
        </Box>
    );
};

export default FrameDetailsPage;
